  "description": "Deprecated. Use `agent-steward` instead. This package is a thin re-export of `agent-steward` for backward compatibility.",
  "license": "MIT",
  "author": "agent-steward contributors",
  "homepage": "https://github.com/DeadSno/agent-steward#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DeadSno/agent-steward.git"
  },
  "bugs": {
    "url": "https://github.com/DeadSno/agent-steward/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "scheduler",
    "deprecated"
  ],
  "main": "index.js",
