    ".": "./index.js",
    "./tui": "./tui.js",
    "./gui-experimental": "./gui-experimental.cjs"
  },
  "files": [
    "index.js",
    "tui.js",
    "gui-experimental.cjs",
    "README.md"
  ],
  "engines": {
    "node": ">=22.22.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "agent-steward": ">=0.0.2"
  }
}

// Thin re-export of agent-steward for backward compatibility.
// The `opencode-windows-scheduler` npm package is deprecated; use `agent-steward` instead.
export * from "agent-steward";
export { default } from "agent-steward";
